      "content": "def decide(policy_status: str, annual_maximum: float, deductible: float, amount: float) -> str:
    """Decide the claim status based on policy status, maximum, and deductible."""
    if policy_status != "ACTIVE":
        return f"REJECTED_POLICY_{policy_status}"
    if amount > annual_maximum:
        return "REJECTED_OVER_LIMIT"
    if amount <= deductible:
        return "REJECTED_BELOW_DEDUCTIBLE"
    return "ACCEPTED"


def payable(amount: float, deductible: float) -> float:
    """Calculate the payable amount after applying the deductible, floored at zero."""
    return max(amount - deductible, 0.0)
